Author: jlaznarte<br>Date: Wed Mar 28 11:40:03 2007<br>New Revision: 35<p>Modified:<br>   trunk/tsDyn/NAMESPACE<br>   trunk/tsDyn/R/nlar-methods.R<br>   trunk/tsDyn/R/star.R<p>Log:<br>Created linearityTest.nlar.struct, to be called from within star(). It has <br>a problem in line 299, where a subindex exceeds the limits. To be fixed in<br>next session.<p><p>Modified: trunk/tsDyn/NAMESPACE<br>==============================================================================<br>--- trunk/tsDyn/NAMESPACE	(original)<br>+++ trunk/tsDyn/NAMESPACE	Wed Mar 28 11:40:03 2007<br>@@ -15,6 +15,7 @@<br> S3method(isLinear, lstar)<br> S3method(addRegime, star)<br> S3method(linearityTest, star)<br>+S3method(linearityTest, nlar.struct)<br> S3method(toLatex, setar)<br> S3method(plot, nlar)<br> S3method(plot, setar)<p>Modified: trunk/tsDyn/R/nlar-methods.R<br>==============================================================================<br>--- trunk/tsDyn/R/nlar-methods.R	(original)<br>+++ trunk/tsDyn/R/nlar-methods.R	Wed Mar 28 11:40:03 2007<br>@@ -243,3 +243,84 @@<br>   res[4] &lt;- &quot;&quot;<br>   return(structure(res, class=&quot;Latex&quot;))<br> }<br>+<br>+<br>+addRegime &lt;- function(object, ...)<br>+  UseMethod(&quot;addRegime&quot;)<br>+<br>+linearityTest &lt;- function(object, ...)<br>+	UseMethod(&quot;linearityTest&quot;)<br>+<br>+# LM linearity testing against 2 regime STAR<br>+#<br>+#   Performs an 3rd order Taylor expansion LM test<br>+#<br>+#   str: an nlar.struct object<br>+#   rob<br>+#   sig<br>+linearityTest.nlar.struct &lt;- function(str, thVar, externThVar=FALSE,<br>+                                      rob=FALSE, sig=0.05, ...)<br>+{<br>+<br>+  T &lt;- NROW(str$xx);  # The number of lagged samples<br>+<br>+  # Build the regressand vector<br>+  y_t &lt;- str$yy;<br>+  <br>+  # Regressors under the null<br>+  xH0 &lt;- cbind(1, str$xx)<br>+<br>+  # Get the transition variable<br>+  s_t &lt;- thVar<br>+<br>+  # Linear Model (null hypothesis)<br>+  linearModel &lt;- lm(y_t ~ . , data=data.frame(xH0))<br>+  u_t &lt;- linearModel$residuals;<br>+  SSE0 &lt;- sum(u_t^2)<br>+<br>+  # Regressors under the alternative<br>+  if (externThVar) {<br>+    tmp &lt;- rep(s_t, NCOL(str$xx) + 1)<br>+    dim(tmp) &lt;- c(length(s_t), NCOL(str$xx) + 1)<br>+    xH1 &lt;- cbind(cbind(1, str$xx) * tmp, cbind(1, str$xx) * (tmp^2),<br>+                 cbind(1, str$xx) * (tmp^3))<br>+  } else {<br>+    tmp &lt;- rep(s_t, NCOL(str$xx))<br>+    dim(tmp) &lt;- c(length(s_t), NCOL(str$xx))<br>+    xH1 &lt;- cbind(str$xx * tmp, str$xx * (tmp^2), str$xx * (tmp^3))<br>+  }<br>+<br>+  # Standarize the regressors<br>+  Z &lt;- cbind(xH0, xH1);<br>+  nZ &lt;- NCOL(Z);<br>+  sdZ &lt;- sd(Z)<br>+  dim(sdZ) &lt;- c(1, nZ)<br>+  sdZ &lt;- kronecker(matrix(1,T,1), sd(Z)) # repeat sdZ T rows<br>+  Z[,2:nZ] &lt;- Z[,2:nZ] / sdZ[,2:nZ]<br>+  #####<br>+  #  ERROR: subindex outside limits<br>+  #####<br>+<br>+  # Nonlinear model (alternative hypothesis)<br>+  nonlinearModel &lt;- lm(u_t ~ ., data=data.frame(Z));<br>+  e_t &lt;- nonlinearModel$residuals;<br>+  SSE1 &lt;- sum(e_t^2)<br>+<br>+  # Compute the test statistic<br>+  n &lt;- dim(xH0)[2];<br>+  m &lt;- dim(xH1)[2];<br>+  <br>+  F = ((SSE0 - SSE1) / m) / (SSE1 / (T - m - n));<br>+    <br>+  # Look up the statistic in the table, get the p-value<br>+  pValue &lt;- pf(F, m, T - m - n, lower.tail = FALSE);<br>+<br>+  if (pValue &lt; sig) {<br>+    return(list(isLinear = TRUE, pValue = pValue));<br>+  }<br>+  else {<br>+    return(list(isLinear = FALSE, pValue = pValue));<br>+  }<br>+<br>+}<br>+<p>Modified: trunk/tsDyn/R/star.R<br>==============================================================================<br>--- trunk/tsDyn/R/star.R	(original)<br>+++ trunk/tsDyn/R/star.R	Wed Mar 28 11:40:03 2007<br>@@ -28,14 +28,11 @@<br> #   series<br> #   rob<br> #   sig<br>-star &lt;- function(x, m, d = 1, steps = d, series, rob = FALSE,<br>-                 sig=.05, maxRegressors, trace=TRUE, control=list(), ...)<br>+star &lt;-